 *   including idle runners that aren't currently executing tasks.
 * @example const { runners, assignments } = useAllRunners({ pollMs: 5000 });
 ***/
export const useAllRunners = ({ pollMs = 5000 } = {}) => {
  const [monitor, setMonitor] = useState(null);
  const [runners, setRunners] = useState(null);

  useEffect(() => {
    let mounted = true;
    let timer = null;
    const load = async () => {
      try {
        const [m, list] = await Promise.all([
          api.getRunnerMonitor().catch(() => null),
          api.getRunners().catch(() => null),
        ]);
        if (!mounted) return;
        if (m) setMonitor(m);
        if (Array.isArray(list)) setRunners(list);
      } catch {
        // Best-effort: stale cards stay until the next poll succeeds.
      }
    };
    void load();
